TLM.f("Sancti/11-10o",{"officium":"Ss. Tryphonis, Respicii, and Nymphæ Martyrum","rule":["vide C3a;"],"fallback":"Commune/C3a","from":{"Tractus":"Commune/C3a","Secreta":"Commune/C3a"},"sections":{"Introitus":[{"k":"ref","la":"Ps 33:18"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"ref","la":"Ps 33:2"},{"k":"text","la":"Benedícam Dóminum in omni témpore: semper laus ejus in ore meo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."}],"Oratio":[{"k":"text","la":"Fac nos, quǽsumus, Dómine, sanctórum Mártyrum tuórum Tryphónis, Respícii et Nymphæ semper festa sectári: quorum suffrágiis, protectiónis tuæ dona sentiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 8:18-23"},{"k":"text","la":"Fratres: Exístimo, quod non sunt condígnæ passiónes hujus témporis ad futúram glóriam, quæ revelábitur in nobis. Nam exspectátio creatúræ revelatiónem filiórum Dei exspéctat. Vanitáti enim creatúra subjécta est, non volens, sed propter eum, qui subjécit eam in spe: quia et ipsa creatúra liberábitur a servitúte corruptiónis, in libertátem glóriæ filiórum Dei. Scimus enim, quod omnis creatúra ingemíscit et párturit usque adhuc. Non solum autem illa, sed et nos ipsi primítias spíritus habéntes: et ipsi intra nos gémimus, adoptiónem filiórum Dei exspectántes, redemptiónem córporis nostri: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 78:10; 78:2"},{"k":"text","la":"Víndica, Dómine, sánguinem Sanctórum tuórum, qui effúsus est."},{"k":"text","la":"Posuérunt mortália servórum tuórum escas volatílibus cœli: carnes Sanctórum tuórum béstiis","mark":"V"},{"k":"text","la":"terræ."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 115:15"},{"k":"text","la":"Pretiósa in conspéctu Dómini mors Sanctórum ejus. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 123:7-8"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium."},{"k":"text","la":"Láqueus contrítus est, et nos liberáti sumus: adjutórium nostrum in nómine Dómini, qui fecit cœlum et terram.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flebant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:1-8"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Atténdite a ferménto pharisæórum, quod est hypócrisis. Nihil autem opértum est, quod non revelétur: neque abscónditum, quod non sciátur. Quóniam, quæ in ténebris dixístis, in lúmine dicéntur: et quod in aurem locúti estis in cubículis, prædicábitur in tectis. Dico autem vobis amícis meis: Ne terreámini ab his, qui occídunt corpus, et post hæc non habent ámplius quid fáciant. Osténdam autem vobis, quem timeátis: timéte eum, qui postquam occíderit, habet potestátem míttere in gehénnam. Ita dico vobis: hunc timéte. Nonne quinque pásseres véneunt dipóndio, et unus ex illis non est in oblivióne coram Deo? Sed et capílli cápitis vestri omnes numeráti sunt. Nolíte ergo timére: multis passéribus pluris estis vos. Dico autem vobis: Omnis, quicúmque conféssus fúerit me coram homínibus, et Fílius hóminis confitébitur illum coram Angelis Dei."}],"Offertorium":[{"k":"ref","la":"Ps 31:11"},{"k":"text","la":"Lætámini in Dómino et exsultáte, justi: et gloriámini, omnes recti corde."}],"Secreta":[{"k":"text","la":"Múnera tibi, Dómine, nostra devotiónis offérimus: quæ et pro tuórum tibi grata sint honóre Justórum, et nobis salutária, te miseránte, reddántur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 12:50"},{"k":"text","la":"Quicúmque fécerit voluntátem Patris mei, qui in cœlis est: ipse meus frater et soror et mater est, dicit Dóminus."}],"Postcommunio":[{"k":"text","la":"Præsta nobis, quǽsumus, Dómine: intercedéntibus sanctis Martýribus tuis Tryphóne, Respício et Nympha; ut, quod ore contíngimus, pura mente capiámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6eeaa4f41117fc66":{"t":"<i>Pomolimo se</i>.\nDaj da uvijek, molimo, Gospodine, slavimo blagdan svetih mučenika tvojih Trifona, Respicija i Nimfe, i da osjećamo po njihovu zatvoru darove tvoje zaštite.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"0b5f9e55c57d534d":{"t":"Prikazujemo ti, Gospodine, darove svoje odanosti, da ti budu mili zbog časti tvojih pravednika, a nama postanu spasonosni po tvom milosrđu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"69e9e83333a7f7bb":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, Gospodine, po zagovoru svojih svetih mučenika Trifona, Respicija i Nimfe, da čistom dušom prihvatimo što smo ustima primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
